/// An ISO 14229-1 identification DID (Annex C): ASCII text of variable length, read
/// with 0x22, never polled. The serial number (0xF18C) and the VIN (0xF190) are
/// personal data and not listed.
final class VehicleIdentification {
  const VehicleIdentification({
    required this.did,
    required this.name,
    required this.label,
    required this.description,
  });

  final int did;
  final String name;
  final String label;
  final String description;
}

