/// Text of an identification answer (the bytes after the DID echo) without its
/// padding (0x00, 0xFF, spaces); a byte outside ASCII becomes U+FFFD.
String decodeIdentificationAscii(List<int> data) {
  bool padding(int b) => b == 0x00 || b == 0xFF || b == 0x20;
  var start = 0;
  var end = data.length;
  while (start < end && padding(data[start])) {
    start++;
  }
  while (end > start && padding(data[end - 1])) {
    end--;
  }
  return String.fromCharCodes(
    data.sublist(start, end).map((b) => b < 0x80 ? b : 0xFFFD),
  );
}
